import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { animalsAPI, breedingAPI } from '../services/api';

const Breeding = () => {
  const [selectedAnimal, setSelectedAnimal] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterGender, setFilterGender] = useState('ALL');

  const { data: animals = [] } = useQuery(['animals'], animalsAPI.getAll);
  const { data: recommendations = [] } = useQuery({
    queryKey: ['recommendations', selectedAnimal?.id],
    queryFn: () => selectedAnimal ? breedingAPI.getRecommendations(selectedAnimal.id) : [],
    enabled: !!selectedAnimal
  });

  const filteredAnimals = animals.filter(animal => {
    const matchesSearch = animal.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         animal.type?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesGender = filterGender === 'ALL' || animal.gender === filterGender;

    return matchesSearch && matchesGender;
  });

  const getScoreClass = (score) => {
    if (score >= 80) return 'score-excellent';
    if (score >= 60) return 'score-good';
    if (score >= 40) return 'score-fair';
    return 'score-poor';
  };

  const getCompatibilityClass = (score) => {
    if (score >= 80) return 'score-excellent';
    if (score >= 60) return 'score-good';
    if (score >= 40) return 'score-fair';
    return 'score-poor';
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>
          <span className="emoji">💕</span>
          Breeding Management
        </h1>
        <p>Find the best breeding pairs and manage your breeding program.</p>
      </div>

      <div className="d-flex justify-between align-center mb-4">
        <button className="btn btn-primary">
          <span className="emoji">📅</span>
          Schedule Breeding
        </button>
      </div>

      <div className="breeding-content">
        <div className="breeding-sidebar">
          <div className="section-card">
            <h2 className="section-title">
              <Users className="farm-icon" />
              Select Animal
            </h2>

            <div className="search-box">
              <Search size={20} />
              <input
                type="text"
                placeholder="Search animals..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="search-input"
              />
            </div>

            <div className="filter-group">
              <Filter size={16} />
              <select
                value={filterGender}
                onChange={(e) => setFilterGender(e.target.value)}
                className="filter-select"
              >
                <option value="ALL">All Genders</option>
                <option value="MALE">Male</option>
                <option value="FEMALE">Female</option>
              </select>
            </div>

            <div className="animals-list">
              {filteredAnimals.map((animal) => (
                <div
                  key={animal.id}
                  className={`animal-item ${selectedAnimal?.id === animal.id ? 'selected' : ''}`}
                  onClick={() => setSelectedAnimal(animal)}
                >
                  <div className="animal-info">
                    <div className="animal-name">{animal.name}</div>
                    <div className="animal-details">
                      <span className="animal-type">{animal.type}</span>
                      <span className={`animal-gender gender-${animal.gender?.toLowerCase()}`}>
                        {animal.gender}
                      </span>
                    </div>
                  </div>
                  <div className="animal-score">
                    <div className={`breeding-score ${getScoreClass(animal.breedingScore)}`}>
                      {animal.breedingScore || 0}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="breeding-main">
          {selectedAnimal ? (
            <div className="section-card">
              <div className="selected-animal-header">
                <div className="animal-info">
                  <h2 className="animal-name">{selectedAnimal.name}</h2>
                  <div className="animal-details">
                    <span className="animal-type">{selectedAnimal.type}</span>
                    <span className={`animal-gender gender-${selectedAnimal.gender?.toLowerCase()}`}>
                      {selectedAnimal.gender}
                    </span>
                    <span className={`animal-status status-${selectedAnimal.healthStatus?.toLowerCase()}`}>
                      {selectedAnimal.healthStatus}
                    </span>
                  </div>
                </div>
                <div className="animal-score">
                  <div className={`breeding-score ${getScoreClass(selectedAnimal.breedingScore)}`}>
                    {selectedAnimal.breedingScore || 0}
                  </div>
                </div>
              </div>

              <div className="recommendations-section">
                <h3 className="section-title">
                  <Target className="farm-icon" />
                  Breeding Recommendations
                </h3>

                {recommendations.length > 0 ? (
                  <div className="recommendations-list">
                    {recommendations.map((rec, index) => (
                      <div key={index} className="recommendation-card">
                        <div className="recommendation-header">
                          <div className="recommendation-pair">
                            {rec.animal1Name} × {rec.animal2Name}
                          </div>
                          <div className={`compatibility-score ${getCompatibilityClass(rec.compatibilityScore)}`}>
                            {rec.compatibilityScore}% Match
                          </div>
                        </div>

                        <div className="recommendation-details">
                          <div className="recommendation-item">
                            <div className="recommendation-label">Reasoning</div>
                            <div className="recommendation-value">{rec.reasoning}</div>
                          </div>
                          <div className="recommendation-item">
                            <div className="recommendation-label">Predicted Value</div>
                            <div className="recommendation-value">
                              {rec.predictedOffspringValue ? `$${rec.predictedOffspringValue}` : 'N/A'}
                            </div>
                          </div>
                          <div className="recommendation-item">
                            <div className="recommendation-label">Predicted Traits</div>
                            <div className="recommendation-value">{rec.predictedTraits || 'N/A'}</div>
                          </div>
                          <div className="recommendation-item">
                            <div className="recommendation-label">Risk Factors</div>
                            <div className="recommendation-value">{rec.riskFactors || 'None identified'}</div>
                          </div>
                        </div>

                        <div className="recommendation-actions">
                          <button className="btn-primary btn-sm">
                            <Calendar size={14} />
                            Schedule Breeding
                          </button>
                          <button className="btn-secondary btn-sm">
                            <TrendingUp size={14} />
                            View Details
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="empty-state">
                    <Target className="empty-state-icon" />
                    <h3 className="empty-state-title">No Recommendations</h3>
                    <p className="empty-state-description">
                      No suitable breeding partners found for this animal.
                    </p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="section-card">
              <div className="empty-state">
                <Heart className="empty-state-icon" />
                <h3 className="empty-state-title">Select an Animal</h3>
                <p className="empty-state-description">
                  Choose an animal from the list to see breeding recommendations.
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Breeding;
